pub fn merge_intervals(xs: List[List[Int]]) -> List[List[Int]] {
  let sorted = xs.sort_by(fn(iv: List[Int]) => iv.get_or(0, 0))
  let start: List[List[Int]] = []
  return sorted.fold(start, fn(acc: List[List[Int]], iv: List[Int]) -> List[List[Int]] {
    let s = iv.get_or(0, 0)
    let e = iv.get_or(1, 0)
    match acc.last() {
      None => { return acc.push([s, e]) },
      Some(last) => {
        let ls = last.get_or(0, 0)
        let le = last.get_or(1, 0)
        if s <= le {
          return acc.set(acc.len() - 1, [ls, le.max(e)])
        }
        return acc.push([s, e])
      },
    }
  })
}
